(()=>{
const D=DealCore,$=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),safeUrl=v=>/^https:\/\//i.test(v||'')?v:'#',phone=v=>String(v||'').replace(/[^+\d]/g,''),email=v=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v||'')?v:'',today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'America/New_York'}),date=v=>v?new Date(v.length===10?v+'T12:00:00':v).toLocaleString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric',year:'numeric',...(v.length>10?{hour:'numeric',minute:'2-digit'}:{})}):'Not supplied';
const bridge=window.DealDeskBridge;let listings=[],buyers=[],meta={},picked=null,view='facts',filter='',county='',timing='upcoming',shortlist=false,busy=false,selectedBuyer='',snapshot=false;
let settings;try{settings=JSON.parse(localStorage.getItem('omdf-desk-settings')||'{}')}catch{settings={}}
const db=()=>bridge.read(),saved=l=>db().leads.find(a=>a.id===l?.id),lead=()=>{const l=listings.find(x=>x.id===picked)||db().leads.find(x=>x.id===picked);return l?{...l,...saved(l),...Object.fromEntries(['saleDate','continuanceDate','effectiveSaleDate','retrievedAt','sourceUrl','sourceName','trustee','dataMode'].filter(k=>l[k]!==undefined).map(k=>[k,l[k]]))}:null},persistSettings=()=>localStorage.setItem('omdf-desk-settings',JSON.stringify(settings));
function toast(s){bridge.toast(s)}function patch(l,values){bridge.patchLead({...l,...values});}
const input=(name,label,value,type='number')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value??'')}" ${type==='number'?'min="0" step="any"':''}></label>`;
function businessList(){const all=[...buyers];for(const i of db().investors){const index=all.findIndex(a=>a.id===i.id);index>=0?all[index]={...all[index],...i}:all.push(i)}return all}
function mapUrl(l){const c=l.coords||saved(l)?.coords;if(c){const p=typeof c==='string'?c.replace(',',','):c.latitude+','+c.longitude;return 'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(p)}return 'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent([l.address,l.city,l.state||'TN',l.zip].filter(Boolean).join(', '))}
function buyScreen(l){let score=0;const reasons=[];if(l.coords||saved(l)?.coords){score++;reasons.push('mapped')}if(['Residential','Multifamily','Land','Commercial'].includes(l.propertyType)){score++;reasons.push('property type recorded')}if(l.lastSalePrice&&l.lastSaleEvidence){score++;reasons.push('last sale supported')}if(l.arv&&l.valuationEvidence){score++;reasons.push('value estimate has evidence')}if(l.status==='Verified'&&l.factsEvidence&&l.verificationDate){score++;reasons.push('property facts verified')}const fit=businessList().some(i=>D.matches(i,l).level>0);if(fit){score++;reasons.push('saved buyer market match')}return {score,max:6,reasons,fit}}
function nextSteps(l){const a=[];if(!l.detail)a.push('Load the original notice and check the latest sale or continuance date.');a.push('Call the trustee/firm using the original notice to confirm whether the sale is active, continued, or canceled.');if(!l.parcel||!l.propertyType||!l.factsEvidence)a.push('Verify parcel, owner/entity, and residential/commercial classification with the county assessor.');if(!l.lastSalePrice||!l.lastSaleEvidence)a.push('Look up the last recorded sale and enter its price, date, and evidence link.');if(!l.coords)a.push('Locate the address, review the map, and confirm the parcel location.');if(!l.arv||!l.valuationEvidence)a.push('Review recent comparable sales, condition, title, and repair costs before setting a buy price.');if(!l.contactVerified)a.push('Use only a verified, authorized contact; record permission and applicable do-not-call checks.');if(!businessList().some(i=>D.matches(i,l).level>0))a.push('Match the property to a buyer’s confirmed market, budget, and property type.');return a.slice(0,6)}
function visible(){const list=shortlist?db().leads:listings;return list.filter(l=>(!county||l.county===county)&&(!filter||[l.address,l.city,l.county,l.zip].join(' ').toLowerCase().includes(filter.toLowerCase()))&&(timing!=='upcoming'||!l.effectiveSaleDate||l.effectiveSaleDate>=today())).filter(l=>{if(!settings.radiusEnabled)return true;const coords=l.coords||saved(l)?.coords;if(!coords)return false;const c=typeof coords==='string'?coords.split(',').map(Number):[coords.latitude,coords.longitude];return c.length===2&&c.every(Number.isFinite)&&settings.center&&D.distance(settings.center,{latitude:c[0],longitude:c[1]})<=Number(settings.radius||25)}).sort((a,b)=>String(a.effectiveSaleDate||'9999').localeCompare(String(b.effectiveSaleDate||'9999')))}
function render(){const items=visible(),l=lead();$('desk').innerHTML=`<div class="desk-head"><div><h1>Find a property. Build the conversation.</h1><p>5 minutes to shortlist · 10 minutes to qualify buyers</p></div><div class="head-buttons"><button class="btn ${!shortlist?'primary':''}" id="deskSource">Sourced properties</button><button class="btn ${shortlist?'primary':''}" id="deskSaved">My shortlist · ${db().leads.length}</button><button class="btn dark" id="deskRefresh" ${busy?'disabled':''}>${busy?'Reading source…':'Refresh source'}</button></div></div><div class="desk-search"><label class="field">Address, city or ZIP<input class="desk-control" id="deskQuery" value="${esc(filter)}" placeholder="e.g. Nashville, 37066"></label><label class="field">County<select id="deskCounty" class="desk-control"><option value="">All available counties</option>${[...new Set(listings.map(x=>x.county).filter(Boolean))].sort().map(c=>`<option ${county===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label class="field">Sale window<select id="deskTiming" class="desk-control"><option value="upcoming" ${timing==='upcoming'?'selected':''}>Upcoming / date missing</option><option value="all" ${timing==='all'?'selected':''}>Include past source dates</option></select></label><button class="btn" id="deskArea">Location & radius</button></div><div class="desk-meta"><strong>${items.length} visible properties</strong> · ${snapshot?'Saved source snapshot':'Fetched source records'} · retrieved ${date(meta.retrievedAt)} ET · ${listings.length}${meta.total?' of '+meta.total:''} public-index rows loaded. Coverage is not exhaustive.</div>${settings.radiusEnabled?`<p class="desk-note">${settings.radius} mi around ${esc(settings.area||'your location')}. Only geocoded properties are included. ${listings.filter(x=>!x.coords&&!saved(x)?.coords).length} source records lack coordinates and are excluded; turn radius off to review them.</p>`:''}<p class="desk-status">Foreclosure notice candidates, not confirmed available inventory. Dates may be continued or canceled. Ownership, condition, asking price and ARV are unverified unless you record evidence.</p><div class="desk-layout"><div class="desk-queue">${items.map(x=>{const sl=saved(x),m=D.math(sl||x);return `<button class="desk-lead ${picked===x.id?'selected':''}" data-pick="${esc(x.id)}"><span class="desk-tag">${esc(x.county||'County not supplied')}</span><span class="desk-tag ${x.effectiveSaleDate&&x.effectiveSaleDate<today()?'alert':''}">${x.effectiveSaleDate?'Source sale '+date(x.effectiveSaleDate):'Sale date not supplied'}</span><strong>${esc(x.address)}</strong><p>${esc(x.city)} · ${esc(x.zip)}</p><div class="desk-mini">${esc(x.trustee||'Manual property')}<br>${m?'Manual max buy '+D.fmt(m.max):'Price / ARV not yet established'}${sl?' · Saved':''}</div></button>`}).join('')||'<div class="desk-blank">No records match. Broaden the area or sale window. Radius searches exclude records without coordinates.</div>'}</div><section class="desk-detail">${l?detail(l):'<div class="desk-blank">Choose a property to see source facts, estimate the deal and prepare outreach.</div>'}</section></div>`;bind();}
function detail(l){return `<div class="desk-title"><span class="desk-tag">${esc(l.dataMode||'Manual')}</span><span class="desk-tag alert">${esc(l.status||'Needs review')}</span><h2>${esc(l.address)}</h2><p>${esc([l.city,l.county?l.county+' County':'',l.state,l.zip].filter(Boolean).join(' · '))}</p><div class="desk-actions"><button class="btn ${saved(l)?'':'primary'}" id="deskShortlist">${saved(l)?'Remove from shortlist':'Add to shortlist'}</button><button class="btn" id="deskSheet">Buyer Deal Sheet</button><a class="btn" href="${esc(mapUrl(l))}" target="_blank" rel="noopener">Open map</a></div></div><div class="desk-tabs">${[['facts','Source & property'],['numbers','Deal numbers'],['outreach','Calls & drafts']].map(([id,name])=>`<button data-view="${id}" class="${view===id?'selected':''}">${name}</button>`).join('')}</div><div class="desk-body">${view==='facts'?facts(l):view==='numbers'?numbers(l):outreach(l)}</div>`}
function facts(l){const conflict=l.detail?.continuanceDate&&l.continuanceDate&&l.detail.continuanceDate!==l.continuanceDate,posted=l.detail?.postedDate,days=posted?Math.max(0,Math.floor((Date.now()-new Date(posted+'T12:00:00').getTime())/86400000)):null,screen=buyScreen(l),contactSearch='https://www.google.com/search?q='+encodeURIComponent((l.trustee||'foreclosure trustee')+' business contact Tennessee');return `<h3>Source facts, ready to review</h3><div class="desk-facts"><div><small>Source listing reason</small>Foreclosure sale notice filed. The index does not state the owner’s reason for default.</div><div><small>Public notice timeline</small>${days===null?'Load notice details to read posted date.':days+' days since posted '+date(posted)}<br><small>This is not the length of delinquency or total time in foreclosure.</small></div><div><small>Original sale date</small>${date(l.saleDate)}</div><div><small>Latest index continuance date</small>${date(l.continuanceDate)}</div><div><small>Trustee / business notice contact</small>${esc(l.trustee||'Not supplied')}<br><small>Trustee is not the property owner.</small></div><div><small>Last recorded sale price</small>${l.lastSalePrice?D.fmt(l.lastSalePrice):'Not supplied'}${l.lastSaleDate?' · '+date(l.lastSaleDate):''}<br><small>County records vary; source required to verify.</small></div><div><small>Property classification</small>${esc(l.propertyType||'Unconfirmed')}<br><small>Confirm with parcel/assessor record.</small></div><div><small>Source retrieved</small>${date(l.retrievedAt)}</div></div><div class="desk-note"><strong>Buy-readiness screen: ${screen.score}/${screen.max}</strong> · ${screen.reasons.length?esc(screen.reasons.join(' · ')):'No verification items completed yet.'}<br>Screening checklist only; it is not an appraisal, title review, or recommendation to buy.</div>${conflict?'<p class="desk-note">Date conflict: index and detail page disagree. Confirm the latest PDF and contact the trustee before relying on the sale date.</p>':''}<p class="desk-source"><a href="${esc(safeUrl(l.sourceUrl))}" target="_blank" rel="noopener">Original property notice</a> · ${esc(l.sourceName||'Manually supplied source')}</p><p class="desk-note">The notice supplies the trustee or firm name, not a verified property-owner phone/email or why the loan defaulted. The app does not search people-finder databases. Use the notice to reach the listed trustee, or look up its public business line: <a href="${esc(contactSearch)}" target="_blank" rel="noopener">Search trustee business contact</a>. Public buyer-company contacts are loaded separately in Calls & drafts.</p><div class="desk-actions"><button class="btn" id="deskNotice">${l.detail?'Reload notice detail':'Read notice in app'}</button><button class="btn" id="deskLocate">${l.coords||saved(l)?.coords?'Refresh map location':'Locate property'}</button><a class="btn" href="${esc(mapUrl(l))}" target="_blank" rel="noopener">Open map</a><a class="btn" href="https://comptroller.tn.gov/office-functions/pa/gisredistricting/redistricting-and-land-use-maps/parcel-data.html" target="_blank" rel="noopener">Tennessee parcel records</a></div><h3>Next steps</h3><ol>${nextSteps(l).map(s=>`<li>${esc(s)}</li>`).join('')}</ol>${l.detail?.pdfUrls?.length?`<details><summary>Original notice PDF · ${l.detail.pdfUrls.length} document(s)</summary><p class="desk-note">Original documents can contain personal information. Use property facts for outreach; do not copy personal circumstances into buyer materials.</p>${l.detail.pdfUrls.map((url,i)=>`<details><summary>Notice document ${i+1}</summary><iframe title="Original foreclosure notice ${i+1}" class="desk-pdf" src="${esc(url)}"></iframe></details>`).join('')}</details>`:''}<form id="deskFacts" class="desk-form"><h3 class="wide">Property facts · record evidence</h3>${input('beds','Beds',l.beds)}${input('baths','Baths',l.baths)}${input('sqft','Square feet',l.sqft)}<label>Property type<select name="propertyType">${['Unconfirmed','Residential','Multifamily','Land','Commercial'].map(t=>`<option ${l.propertyType===t?'selected':''}>${t}</option>`).join('')}</select></label>${input('parcel','Parcel / GISLINK',l.parcel,'text')}${input('ownerBusiness','Owner / owning entity · record confirmed name',l.ownerBusiness,'text')}${input('lastSalePrice','Last recorded sale price',l.lastSalePrice)}${input('lastSaleDate','Last recorded sale date',l.lastSaleDate,'date')}${input('lastSaleEvidence','Sale record evidence URL',l.lastSaleEvidence,'url')}${input('factsEvidence','Property / ownership evidence URL',l.factsEvidence,'url')}${input('verificationDate','Date checked',l.verificationDate,'date')}<label>Status<select name="status">${['Needs review','Verified','Contacted','Closed / archive'].map(t=>`<option ${l.status===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="wide">Shareable property condition summary<textarea name="publicCondition" placeholder="Physical property facts only; this field appears in buyer materials.">${esc(l.publicCondition||'')}</textarea></label><label class="wide">Internal verification notes · excluded from buyer materials<textarea name="internalNotes">${esc(l.internalNotes||'')}</textarea></label><button class="btn primary">Save property facts</button></form>`}
function numbers(l){const m=D.math(l);return `<h3>Price the opportunity</h3><p class="desk-note">No automated appraisal or asking price is supplied by these notices. Add supported estimates before relying on a spread.</p><form id="deskNumbers" class="desk-form">${input('arv','ARV estimate',l.arv||'')}${input('sellerTarget','Seller target / contract price',l.sellerTarget)}${input('fee','Desired gross assignment fee',l.fee??10000)}${input('repairLow','Repairs · low',l.repairLow)}${input('repairBase','Repairs · base',l.repairBase??l.repairs)}${input('repairHigh','Repairs · high',l.repairHigh)}${input('percent','Investor % of ARV',l.percent??70)}${input('costs','Investor closing / holding costs',l.costs??0)}${input('assignmentCosts','Your assignment costs',l.assignmentCosts??0)}<label class="wide">Valuation evidence / adjustment notes<input name="valuationEvidence" value="${esc(l.valuationEvidence||'')}" placeholder="Source, condition and comp adjustments"></label><button class="btn primary">Update deal</button></form><div class="desk-math"><div><small>Investor max · base repairs</small><strong>${m?D.fmt(m.max):'Needs estimates'}</strong></div><div><small>Projected gross fee at max buy</small><strong>${D.fmt(m?.gross)}</strong></div><div><small>After your assignment costs</small><strong>${D.fmt(m?.net)}</strong></div></div>${m&&m.gross<0?'<p class="desk-warning">Negative projected spread. Seller target exceeds the investor maximum.</p>':''}<details open><summary>Explain the Math</summary><p>Investor max = ARV × investor percentage − repairs − investor costs.<br>Seller contract ceiling = investor max − desired fee.<br>Projected gross fee = investor price − seller contract price. The projection above assumes the buyer pays the maximum; actual fee depends on the negotiated price.<br>Net after your costs = gross fee − assignment costs.</p>${m?`<p>Contract ceiling: <strong>${D.fmt(m.ceiling)}</strong> · Proposed buyer ask: <strong>${D.fmt(m.buyerAsk)}</strong></p>`:''}</details><div class="table-wrap"><table><tr><th>Formula</th><th>Low repairs</th><th>Base repairs</th><th>High repairs</th></tr>${[65,70,75].map(n=>`<tr><td>${n}% ARV</td>${['repairLow','repairBase','repairHigh'].map(k=>`<td>${D.fmt(D.math(l,n,l[k])?.max)}</td>`).join('')}</tr>`).join('')}</table></div><details><summary>Comparable sales · manual evidence</summary>${(l.comps||[]).map(c=>`<p>${esc(c.address)} · ${D.fmt(c.price)} · ${c.sqft} sq ft · ${date(c.date)}<br>${esc(c.source)}</p>`).join('')}<form id="deskComp" class="desk-form">${input('address','Comp address','','text')}${input('price','Sold price','')}${input('sqft','Square feet','')}${input('date','Sale date','','date')}${input('source','Evidence source URL','','url')}<button class="btn">Add comp</button></form><div class="desk-actions"><button class="btn" id="deskCompArv">Use median comp $/sq ft</button></div></details>`}
function investorCards(l){const all=businessList().map(i=>({i,m:D.matches(i,l)})).sort((a,b)=>b.m.level-a.m.level);return all.map(({i,m})=>`<div class="desk-business"><span class="desk-tag ${m.level?'good':''}">${esc(m.label)}</span><h3>${esc(i.name)}</h3><p>${esc(i.city)} · ${esc(i.type||'Investor')}<br>${esc(i.notes||'Buy box not recorded')}</p><p>Business contact source checked ${date(i.sourceDate)} · <a href="${esc(safeUrl(i.source))}" target="_blank" rel="noopener">Source</a></p><div class="desk-actions">${i.phone&&!D.blocked(i)?`<a class="btn" href="tel:${phone(i.phone)}">Call ${esc(i.phone)}</a>`:''}<button class="btn primary" data-draft="${esc(i.id)}" ${D.blocked(i)?'disabled':''}>Prepare text / email</button><button class="btn" data-buybox="${esc(i.id)}">Edit buy box / contact</button></div>${D.blocked(i)?'<p class="desk-warning">Contact suppressed by opt-out / DNC.</p>':''}</div>`).join('')}
function outreach(l){return `<h3>First: qualify the seller and property</h3><p>Owner / entity: <strong>${esc(l.ownerBusiness||'Not verified from property records')}</strong>. The notice trustee is a separate role.</p><form id="deskContact" class="desk-form">${input('sender','Your name / company',settings.sender,'text')}${input('role','Your role',settings.role||'a real estate professional','text')}${input('ownerPhone','Owner / authorized contact phone',l.ownerPhone,'tel')}${input('ownerEmail','Owner / authorized contact email',l.ownerEmail,'email')}${input('contactSource','Contact source / permission evidence',l.contactSource,'text')}${input('contactCheckedDate','Contact verified date',l.contactCheckedDate,'date')}<div class="wide"><label class="desk-check"><input type="checkbox" name="contactVerified" ${l.contactVerified?'checked':''}>Contact identity, permission and applicable DNC checks completed</label><label class="desk-check"><input type="checkbox" name="dnc" ${l.dnc?'checked':''}>Do not contact</label><label class="desk-check"><input type="checkbox" name="optout" ${l.optout?'checked':''}>Contact opted out</label><label class="desk-check"><input type="checkbox" name="equitableInterest" ${l.equitableInterest?'checked':''}>I hold a valid assignable contract / equitable interest</label></div><button class="btn primary">Save contact & permissions</button></form><p class="desk-mini">Personal contact details are entered by you from permitted sources; no people-search lookup is connected. Company contact info is labeled separately. Nothing is sent automatically.</p>${D.blocked(l)?'<p class="desk-warning">Seller contact suppressed. Call and draft actions disabled.</p>':!l.contactVerified?'<p class="desk-note">Verify contact identity and complete permission/DNC checks to enable seller call and drafts.</p>':`<div class="desk-person"><textarea class="desk-draft" id="deskSellerDraft" readonly>${esc(D.sellerDraft(l,settings.sender,settings.role))}</textarea><div class="desk-actions">${l.ownerPhone?`<a class="btn" href="tel:${phone(l.ownerPhone)}">Call contact</a><a class="btn" href="sms:${phone(l.ownerPhone)}?body=${encodeURIComponent(D.sellerDraft(l,settings.sender,settings.role))}">Open text draft</a>`:''}${email(l.ownerEmail)?`<a class="btn" href="mailto:${encodeURIComponent(l.ownerEmail)}?subject=${encodeURIComponent('Property inquiry: '+l.address)}&body=${encodeURIComponent(D.sellerDraft(l,settings.sender,settings.role))}">Open email draft</a>`:''}<button class="btn" id="deskCopySeller">Copy seller script</button></div></div>`}<h3>Then: qualify investors</h3><p class="desk-mini">Published company contacts, not endorsed or financially vetted buyers. Market fit is a starting point; confirm funds, price ceiling and assignment acceptance.</p>${investorCards(l)}<form id="deskLog" class="desk-form"><h3 class="wide">Track the negotiation</h3><label>Contact / company<select name="target"><option value="seller">Seller / owner contact</option>${businessList().map(i=>`<option value="${esc(i.id)}">${esc(i.name)}</option>`).join('')}</select></label><label>Outcome<select name="outcome"><option>Called · no answer</option><option>Interested</option><option>Offer received</option><option>Follow-up requested</option><option>Not a fit</option><option>Opt-out received</option></select></label>${input('offer','Investor proposed price','')}${input('followup','Next follow-up',l.followup,'date')}<label class="wide">Conversation note · internal only<textarea name="note"></textarea></label><button class="btn">Save activity</button></form>${(l.activity||[]).slice().reverse().slice(0,12).map(a=>`<div class="desk-logs"><strong>${esc(a.who)} · ${esc(a.outcome)}</strong> · ${date(a.at)}<br>${a.offer?D.fmt(a.offer)+' · ':''}${esc(a.note)}</div>`).join('')}`}
function bind(){document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{picked=b.dataset.pick;render()});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});$('deskRefresh').onclick=()=>load(true);$('deskSource').onclick=()=>{shortlist=false;render()};$('deskSaved').onclick=()=>{shortlist=true;timing='all';picked=db().leads[0]?.id||picked;render()};$('deskQuery').onchange=e=>{filter=e.target.value;render()};$('deskCounty').onchange=e=>{county=e.target.value;render()};$('deskTiming').onchange=e=>{timing=e.target.value;render()};$('deskArea').onclick=areaDialog;const l=lead();if(!l)return;
 if($('deskShortlist'))$('deskShortlist').onclick=()=>{if(saved(l)){bridge.removeLead(l.id);if(shortlist){picked=db().leads[0]?.id||null;render()}else render();toast('Removed from your shortlist')}else{patch(l,{type:l.kind||l.type||'Foreclosure',status:l.status||'Needs review',sourceDate:today()});toast('Added to your shortlist')}};if($('deskSheet'))$('deskSheet').onclick=()=>printSheet(l);
 if($('deskNotice'))$('deskNotice').onclick=async()=>{if(!l.sourceId)return toast('No connected notice detail for this manual lead.');toast('Reading original notice…');try{const r=await fetch('/api/notice/'+l.sourceId);const d=await r.json();if(!r.ok)throw Error(d.error);patch(l,{detail:d});toast('Notice details loaded. Dates still require verification.')}catch(e){toast('Notice unavailable: '+e.message)}};
 if($('deskLocate'))$('deskLocate').onclick=async()=>{toast('Locating property with the US Census Geocoder…');try{const r=await fetch('/api/geocode?'+new URLSearchParams({address:[l.address,l.city,'TN',l.zip].filter(Boolean).join(', ')}));const d=await r.json();if(!r.ok)throw Error(d.error);patch(l,{coords:d.coords,geocode:d});toast('Coordinates saved from '+d.source)}catch(e){toast(e.message)}};
 form('deskFacts',d=>{if(d.status==='Verified'&&(!d.factsEvidence||!d.verificationDate))throw Error('Verified facts require evidence and a date.');const values={...d};for(const k of ['beds','baths','sqft','lastSalePrice'])values[k]=numeric(d,k);patch(l,values)});
 form('deskNumbers',d=>{const values={};for(const k of ['arv','sellerTarget','fee','repairLow','repairBase','repairHigh','percent','costs','assignmentCosts'])values[k]=numeric(d,k);if(values.percent===null||values.percent>100)throw Error('Percentage must be between 0 and 100.');const r=[values.repairLow,values.repairBase,values.repairHigh];if(r.every(v=>v!==null)&&(r[0]>r[1]||r[1]>r[2]))throw Error('Repair estimates must follow low ≤ base ≤ high.');values.valuationEvidence=d.valuationEvidence;patch(l,values)});
 form('deskComp',d=>{if(!d.address||!d.date||!d.source)throw Error('Provide comp address, date and source.');const price=numeric(d,'price'),sqft=numeric(d,'sqft');if(!price||!sqft)throw Error('Comp price and size must be positive.');patch(l,{comps:[...(l.comps||[]),{...d,price,sqft}]})});if($('deskCompArv'))$('deskCompArv').onclick=()=>{if(!l.sqft||(l.comps||[]).length<2)return toast('Enter subject square feet and at least two comps first.');const rates=l.comps.map(c=>c.price/c.sqft).sort((a,b)=>a-b),mid=Math.floor(rates.length/2);patch(l,{arv:Math.round((rates.length%2?rates[mid]:(rates[mid-1]+rates[mid])/2)*l.sqft),valuationEvidence:'Median manual comp $/sq ft; adjustment review required.'})};
 form('deskContact',(d,f)=>{if(f.contactVerified.checked&&(!d.contactSource||!d.contactCheckedDate))throw Error('Provide contact verification evidence and date.');settings.sender=d.sender;settings.role=d.role;persistSettings();patch(l,{ownerPhone:d.ownerPhone,ownerEmail:d.ownerEmail,contactSource:d.contactSource,contactCheckedDate:d.contactCheckedDate,contactVerified:f.contactVerified.checked,dnc:f.dnc.checked,optout:f.optout.checked,equitableInterest:f.equitableInterest.checked})});if($('deskCopySeller'))$('deskCopySeller').onclick=()=>copy($('deskSellerDraft').value);
 document.querySelectorAll('[data-draft]').forEach(b=>b.onclick=()=>draftDialog(l,businessList().find(i=>i.id===b.dataset.draft)));document.querySelectorAll('[data-buybox]').forEach(b=>b.onclick=()=>buyerDialog(businessList().find(i=>i.id===b.dataset.buybox)));
 form('deskLog',d=>{const contact=businessList().find(i=>i.id===d.target),a={...d,who:contact?.name||'Seller / owner contact',at:new Date().toISOString(),offer:numeric(d,'offer')};if(d.outcome==='Opt-out received'&&contact)bridge.patchInvestor({...contact,optout:true});patch(l,{followup:d.followup,activity:[...(l.activity||[]),a],...(d.outcome==='Opt-out received'&&!contact?{optout:true}:{})});toast('Activity recorded manually. No message was sent.')});}
function numeric(d,k){if(d[k]===''||d[k]===undefined)return null;const n=Number(d[k]);if(!Number.isFinite(n)||n<0)throw Error('Enter a valid '+k);return n}
function form(id,fn){if($(id))$(id).onsubmit=e=>{e.preventDefault();try{fn(Object.fromEntries(new FormData(e.target)),e.target.elements)}catch(err){toast(err.message)}}}
async function copy(s){try{await navigator.clipboard.writeText(s);toast('Copied. Review before sending.')}catch{toast('Clipboard unavailable. Select and copy the draft manually.')}}
function dialog(title,content){let el=$('deskDialog');if(!el){el=document.createElement('dialog');el.id='deskDialog';el.className='modal';document.body.append(el)}el.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="btn" id="deskClose">Close</button></div><div class="modal-content">${content}</div>`;$('deskClose').onclick=()=>el.close();el.showModal();return el}
function draftDialog(l,i){if(D.blocked(i))return toast('Contact suppressed.');selectedBuyer=i.id;const d=D.investorDraft(l,i,settings.sender,'email'),sms=D.investorDraft(l,i,settings.sender,'sms');dialog('Investor draft · '+i.name,`<p class="desk-note">${l.equitableInterest?'Confirm disclosures and contract terms before presenting an assignment.':'You have not recorded equitable interest. This draft asks about buyer interest and does not claim a contract.'} Drafts exclude owner contact, internal notes and personal motivation. Opening your mail/text app does not send a message.</p><label class="field">Subject<input class="desk-control" id="deskEmailSubject" value="${esc(d.subject)}"></label><label class="field">Email body<textarea class="desk-draft" id="deskEmailBody">${esc(d.body)}</textarea></label><label class="field">Text body<textarea class="desk-draft" id="deskTextBody">${esc(sms.body)}</textarea></label><div class="desk-actions"><button class="btn" id="copyEmail">Copy email</button><button class="btn" id="copyText">Copy text</button>${email(i.email)?'<button class="btn primary" id="openEmail">Open email draft</button>':'<span class="desk-mini">No verified email listed; copy the draft or record an email.</span>'}${i.phone?'<button class="btn primary" id="openText">Open text draft</button>':''}</div><p class="desk-mini">Text capability is unconfirmed unless the business advertises it. Confirm permission, company identity and assignment acceptance before outreach. Do not add sensitive research to these drafts.</p>`);$('copyEmail').onclick=()=>copy($('deskEmailSubject').value+'\n\n'+$('deskEmailBody').value);$('copyText').onclick=()=>copy($('deskTextBody').value);if($('openEmail'))$('openEmail').onclick=()=>{location.href=`mailto:${encodeURIComponent(i.email)}?subject=${encodeURIComponent($('deskEmailSubject').value)}&body=${encodeURIComponent($('deskEmailBody').value)}`};if($('openText'))$('openText').onclick=()=>{location.href=`sms:${phone(i.phone)}?body=${encodeURIComponent($('deskTextBody').value)}`};}
function buyerDialog(i){dialog('Save investor buy box',`<form id="deskBuyerForm" class="desk-form">${input('name','Company / name',i.name,'text')}${input('city','Primary market',i.city,'text')}${input('counties','Counties · comma separated',(i.counties||[]).join(', '),'text')}${input('phone','Business / permitted phone',i.phone,'tel')}${input('email','Business / permitted email',i.email,'email')}${input('budget','Maximum purchase price',i.budget)}${input('maxRepairs','Maximum repair budget',i.maxRepairs)}${input('source','Contact source',i.source,'url')}${input('sourceDate','Source checked',i.sourceDate,'date')}<label class="wide">Buy box / notes<textarea name="notes">${esc(i.notes)}</textarea></label><div class="wide"><label class="desk-check"><input name="buyBoxConfirmed" type="checkbox" ${i.buyBoxConfirmed?'checked':''}>Buy box confirmed directly</label><label class="desk-check"><input name="dnc" type="checkbox" ${i.dnc?'checked':''}>Do not contact</label><label class="desk-check"><input name="optout" type="checkbox" ${i.optout?'checked':''}>Opted out</label></div><button class="btn primary">Save investor</button></form>`);form('deskBuyerForm',(d,f)=>{const values={...i,...d,counties:d.counties.split(',').map(s=>s.trim()).filter(Boolean),budget:numeric(d,'budget'),maxRepairs:numeric(d,'maxRepairs'),buyBoxConfirmed:f.buyBoxConfirmed.checked,dnc:f.dnc.checked,optout:f.optout.checked};bridge.patchInvestor(values);$('deskDialog').close();render()})}
function areaDialog(){dialog('Location & radius',`<p class="desk-mini">Radius filtering uses property coordinates. Records without a verified geocode are excluded. Use the property panel to locate a record.</p><div class="desk-actions"><button class="btn" id="deskGeo">Use current location</button></div><form id="deskAreaForm" class="desk-form"><label class="wide">ZIP / city / county preset<select name="preset"><option value="">Manual coordinates</option><option value="36.1627,-86.7816">Nashville / Davidson / 37201</option><option value="36.2081,-86.2911">Lebanon / Wilson / 37087</option><option value="36.3884,-86.4467">Gallatin / Sumner / 37066</option><option value="35.9606,-83.9207">Knoxville / Knox / 37902</option><option value="35.1495,-90.049">Memphis / Shelby / 38103</option><option value="35.6151,-87.0353">Columbia / Maury / 38401</option></select></label>${input('latitude','Latitude',settings.center?.latitude)}${input('longitude','Longitude',settings.center?.longitude)}<label>Radius<select name="radius">${[5,10,15,25,50,75,100].map(n=>`<option ${Number(settings.radius||25)===n?'selected':''}>${n}</option>`).join('')}<option value="custom">Custom</option></select></label>${input('custom','Custom miles','')}<label class="wide desk-check"><input type="checkbox" name="enabled" ${settings.radiusEnabled?'checked':''}>Enable radius filter</label><button class="btn primary">Apply radius</button></form>`);$('deskAreaForm').elements.latitude.removeAttribute('min');$('deskAreaForm').elements.longitude.removeAttribute('min');$('deskGeo').onclick=()=>{if(!navigator.geolocation)return toast('Geolocation unavailable.');navigator.geolocation.getCurrentPosition(pos=>{settings.center={latitude:pos.coords.latitude,longitude:pos.coords.longitude};settings.area='Current location';$('deskAreaForm').elements.latitude.value=pos.coords.latitude;$('deskAreaForm').elements.longitude.value=pos.coords.longitude;toast('Location read; apply radius to filter.')},()=>toast('Location unavailable; use preset or manual coordinates.'),{timeout:10000})};form('deskAreaForm',(d,f)=>{const coords=d.preset?d.preset.split(',').map(Number):[Number(d.latitude),Number(d.longitude)],r=d.radius==='custom'?Number(d.custom):Number(d.radius);if(f.enabled.checked&&((!d.preset&&(!d.latitude||!d.longitude))||coords.some(n=>!Number.isFinite(n))||Math.abs(coords[0])>90||Math.abs(coords[1])>180||!r||r>1000))throw Error('Enter valid coordinates and radius (up to 1,000 miles).');settings.center={latitude:coords[0],longitude:coords[1]};settings.radius=r;settings.radiusEnabled=f.enabled.checked;if(d.preset)settings.area=f.preset.options[f.preset.selectedIndex].text;persistSettings();$('deskDialog').close();render()})}
function printSheet(l){const d=D.safeDeal(l);let el=$('deskPrint');if(!el){el=document.createElement('div');el.id='deskPrint';document.body.append(el)}el.innerHTML=`<article class="desk-buyer-sheet"><h1>Buyer Deal Sheet</h1><h2>${esc(d.address)}</h2><p>${esc([d.city,d.state,d.zip].filter(Boolean).join(', '))} · ${esc(d.propertyType)}</p><p>${d.beds??'—'} beds · ${d.baths??'—'} baths · ${d.sqft??'—'} sq ft</p><div class="sheet-grid"><div>Proposed buyer price<strong>${D.fmt(d.buyerAsk)}</strong></div><div>Manual ARV estimate<strong>${D.fmt(d.arv)}</strong></div><div>Repairs · low / base / high<strong>${D.fmt(d.repairLow)} / ${D.fmt(d.repairBase)} / ${D.fmt(d.repairHigh)}</strong></div><div>Scenario max buy<strong>${D.fmt(d.maxBuy)}</strong></div></div><p>Condition: ${esc(d.publicCondition)}</p><h3>Comparable sales</h3>${d.comps.length?d.comps.map(c=>`<p>${esc(c.address)} · ${D.fmt(c.price)} · ${c.sqft} sq ft · ${date(c.date)}</p>`).join(''):'<p>No sold comps supplied. ARV has not been substantiated.</p>'}<p>${d.equitableInterest?'Potential assignment subject to verified contract and disclosure terms.':'Research opportunity only. No assignable contract has been recorded.'}</p><p>Estimates require independent review of value, condition, title, costs, access and closing terms. No return or profit is guaranteed.</p></article>`;document.body.classList.add('desk-print');window.print();setTimeout(()=>document.body.classList.remove('desk-print'),1000)}
async function load(refresh=false){busy=true;render();try{const r=await fetch(refresh?'/api/listings':'/listings.json',{cache:'no-store'}),v=await r.json();if(!r.ok||!Array.isArray(v.items))throw Error(v.error||'Source unavailable');listings=v.items;meta=v;snapshot=!refresh;if(!picked)picked=visible()[0]?.id||listings[0]?.id;toast(refresh?'Source refreshed. These remain unverified notice candidates.':'Source snapshot loaded. Use Refresh source for current records.')}catch(e){toast('Refresh failed. Keeping the prior snapshot: '+e.message)}finally{busy=false;render()}}
window.addEventListener('deal-print',e=>printSheet(e.detail));window.addEventListener('deal-show-buyers',()=>{view='outreach';render()});
window.addEventListener('deal-workspace-changed',()=>{if($('desk')?.classList.contains('active'))render()});
fetch('/buyers.json').then(r=>r.json()).then(v=>{buyers=v;render()}).catch(()=>toast('Business contact directory unavailable. Saved contacts remain available.'));load();
})();
